Przykladowe rozwiazanie (C++):

int maxL = 0, maxW;
for (int i = 0; i < N; i++) {
  W = Zbior[i];
  L = 0;
  for (int j = 0; j < N; j++)
    if (Zbior[j] == W) L++;
  if (L > maxL) {
    maxL = L;
    maxW = W;
  }
}
cout << " Moda = " << maxW;

Algorytm zlicza wystapienia kazdego elementu i zapamietuje ten o najwiekszej liczbie wystapien.
